  "track.animation.m.phaseread.s.where.layout": "`Modifier.offset { }` reads `x` in a lambda that runs in the placement step of Layout.",
  "track.animation.m.phaseread.s.where.draw": "`graphicsLayer { translationX = x }` reads `x` in a lambda that runs in the draw phase.",
  "track.animation.m.phaseread.ev.where.composition": "read in composition",
