  "track.animation.m.segment.s.target.title": "The target becomes Expanded: three children start together",
  "track.animation.m.segment.s.target.explain": "Every time the composable runs, `updateTransition` calls `transition.animateTo(target)`. The new target makes every child start towards Expanded's values, each following its own `transitionSpec`.",
  "track.animation.m.segment.ev.target": "The target becomes Expanded: three children start together",
  "track.animation.m.segment.s.enter.title": "It runs as soon as it enters composition",
