  "track.animation.m.clockstart.st.auto": "autoAdvance",
  "track.animation.m.clockstart.st.play": "Play time",
  "track.animation.m.clockstart.st.sees": "Test sees",
  "track.animation.m.clockstart.s.intro.manual.title": "Holding the clock: autoAdvance = false",
  "track.animation.m.clockstart.s.intro.manual.explain": "The test holds the clock: there are no frames unless the test advances it.",
  "track.animation.m.clockstart.ev.intro.manual": "Holding the clock: autoAdvance = false",
  "track.animation.m.clockstart.s.intro.ignore.title": "autoAdvance = false; will call advanceTimeBy(50, ignoreFrameDuration = true)",
  "track.animation.m.clockstart.s.intro.ignore.explain": "The `ignoreFrameDuration` parameter turns off rounding up to a multiple of the frame.",
  "track.animation.m.clockstart.ev.intro.ignore": "autoAdvance = false; will call advanceTimeBy(50, ignoreFrameDuration = true)",
  "track.animation.m.clockstart.s.intro.auto.title": "autoAdvance = true (default)",
  "track.animation.m.clockstart.s.intro.auto.explain": "While awaiting idleness, the framework advances the clock itself until no recomposition or animation is pending.",
  "track.animation.m.clockstart.ev.intro.auto": "autoAdvance = true (default)",
  "track.animation.m.clockstart.s.toggle.title": "enabled = true: nothing happens yet",
  "track.animation.m.clockstart.s.toggle.explain": "Writing state only marks a recomposition as needed; recomposition only runs when the clock produces a frame (except the initial composition in setContent).",
  "track.animation.m.clockstart.ev.toggle": "enabled = true: nothing happens yet",
  "track.animation.m.clockstart.s.f1.title": "Frame 1 at {clock} ms: recompose, the animation is scheduled",
  "track.animation.m.clockstart.s.f1.explain": "This frame sends the time to animations FIRST (none is waiting yet), then recomposes; during recomposition the animation is scheduled to start. There is no play time yet.",
  "track.animation.m.clockstart.ev.f1": "Frame 1 at {clock} ms: recompose, the animation is scheduled",
  "track.animation.m.clockstart.s.f2.title": "Frame 2 at {clock} ms: the animation gets its first frame, play time = 0",
  "track.animation.m.clockstart.s.f2.explain": "Exactly the KDoc example: flip the state then `advanceTimeBy(32)`, and the animation's play time is STILL 0 ms.",
  "track.animation.m.clockstart.ev.f2": "Frame 2 at {clock} ms: the animation gets its first frame, play time = 0",
  "track.animation.m.clockstart.s.adv.title": "advanceTimeBy(50) → advances {adv} ms, play time {play} ms",
  "track.animation.m.clockstart.s.adv.explain": "50 is rounded up to 64 (four 16 ms frames) so the same number of frames is always produced wherever the clock is.",
  "track.animation.m.clockstart.ev.adv": "advanceTimeBy(50) → advances {adv} ms, play time {play} ms",
  "track.animation.m.clockstart.s.advIgnore.title": "advanceTimeBy(50, ignoreFrameDuration = true): clock at {clock} ms",
  "track.animation.m.clockstart.s.advIgnore.explain": "No rounding: the clock stops at 50, but frames only happen at 16, 32, 48. The KDoc: the last few milliseconds may not be observed by anyone, since most work only happens on a frame. Play time {play} ms.",
  "track.animation.m.clockstart.ev.advIgnore": "advanceTimeBy(50, ignoreFrameDuration = true): clock at {clock} ms",
  "track.animation.m.clockstart.s.idle.title": "Awaiting idle: the clock advances until the animation ends",
  "track.animation.m.clockstart.s.idle.explain": "With autoAdvance, a running animation means not idle, so the framework keeps advancing. By the time the test checks, the animation is at its end.",
  "track.animation.m.clockstart.ev.idle": "Awaiting idle: the clock advances until the animation ends",
  "track.animation.m.clockstart.s.done.manual.title": "Check the intermediate value at play time {play} ms",
  "track.animation.m.clockstart.s.done.manual.explain": "The docs' example compares a screenshot with a golden image here.",
  "track.animation.m.clockstart.ev.done.manual": "Check the intermediate value at play time {play} ms",
  "track.animation.m.clockstart.s.done.ignore.title": "Play time {play} ms, less than you might think",
  "track.animation.m.clockstart.s.done.ignore.explain": "The clock is at 50 but the animation only saw up to frame 48 (after the 2 start-up frames). Turn rounding off only when you really need an odd time mark.",
  "track.animation.m.clockstart.ev.done.ignore": "Play time {play} ms, less than you might think",
  "track.animation.m.clockstart.s.done.auto.title": "The test only sees the final value",
  "track.animation.m.clockstart.s.done.auto.explain": "Good for checking the state after the animation; useless for checking intermediate values.",
  "track.animation.m.clockstart.ev.done.auto": "The test only sees the final value",
  "track.animation.m.clockstart.co.drives": "MainTestClock's KDoc: this clock drives all recompositions, all withFrameNanos subscribers (all Compose animations) and all LaunchedEffects; if it does not tick, animations are frozen. [[src:ui-testclock-src]]",
  "track.animation.m.clockstart.co.twoframes": "The KDoc: animations receive the frame time before recomposition, so they do not get their start time in the first frame after flipping state; with 16 ms frames, advanceTimeBy(32) still leaves the play time at 0. [[src:ui-testclock-src]]",
  "track.animation.m.clockstart.co.round": "The KDoc: rounding up to a multiple of the frame always produces the same number of frames; a frame is 16 ms on the JVM (Android and Desktop). [[src:ui-testclock-src]] [[src:an-testing]]",
  "track.animation.m.clockstart.co.auto": "The KDoc: autoAdvance is true by default; the framework advances the clock while awaiting idleness so no recompositions or animations remain pending. [[src:ui-testclock-src]]",
  "track.animation.cap.clockstart": "The test on the left advances the clock; each frame, the clock sends the time to the animation first and then to recomposition.",
  "track.animation.c8.sim.animation.clockstart": "On which frame an animation starts",
  "track.animation.c8.sim.animation.testclock": "Time rounding lab",
  "track.animation.c8.quiz.q3.q": "Does advanceTimeBy(50, ignoreFrameDuration = true) produce a frame at 50 ms?",
  "track.animation.c8.quiz.q3.a": "No.",
  "track.animation.c8.quiz.q3.why": "Frames only occur at multiples of 16 ms; the last few milliseconds may go unobserved.",
